double americanPut(double S, double K, double T, double r, double v, int n) {
    double dt = T / n, u = exp(v * sqrt(dt)), d = 1 / u, p = (exp(r * dt) - d) / (u - d), disc = exp(-r * dt);
    vector<double> val(n + 1); for (int j = 0; j <= n; j++) val[j] = max(K - S * pow(u, j) * pow(d, n - j), 0.0);
    for (int i = n - 1; i >= 0; i--) for (int j = 0; j <= i; j++) val[j] = max(disc * (p * val[j + 1] + (1 - p) * val[j]), K - S * pow(u, j) * pow(d, i - j));
    return val[0];
}
